SELECT bucket, count(*) rows, to_char(sum(amount),'FM99,99,99,999') amount
  FROM public.finance_transactions GROUP BY bucket ORDER BY sum(amount) DESC;
SELECT count(*) total, min(txn_date) first, max(txn_date) last,
       count(*) FILTER (WHERE note IS NOT NULL) date_estimated
  FROM public.finance_transactions;